import type { MetadataRoute } from "next";
import lastmodMap from "@/data/lastmod-map.json";

const BASE_URL = "https://www.myparamountlab.com";

// Route -> last-modified date, pre-generated by scripts/generate-lastmod-map.js
// from full git history. This is NOT computed at build/request time: Vercel's
// build checkout is shallow, so shelling out to `git log` there silently
// returns nothing for older commits and falls back to the build timestamp
// for most routes. Re-run that script locally (where full history exists)
// and commit the updated JSON whenever a page's content changes.
const routes = Object.keys(lastmodMap) as (keyof typeof lastmodMap)[];

export default function sitemap(): MetadataRoute.Sitemap {
  return routes.map((path) => ({
    url: `${BASE_URL}${path}`,
    lastModified: new Date(lastmodMap[path]),
  }));
}
